// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(address actor, address victim, bytes32 role) public {
        // A renounce of someone else's role must never be possible by a third party:
        // the reference reverts with AccessControlBadConfirmation whenever
        // msg.sender != callerConfirmation, for ANY role and ANY victim.
        vm.assume(actor != victim);
        vm.prank(actor);
        bool ok;
        try c.renounceRole(role, victim) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: a third-party renounce always reverts (ok == false for every input).
        // Mutant: the caller-mismatch check is removed, so the call succeeds (ok == true).
        assertTrue(!ok);
    }
}
